<script setup lang="ts">
import{onMounted,onUnmounted,ref}from'vue';import{request}from'../../api/client';import{message,all}from'../sites/data';import{useAuth}from'../auth/store';import type{Site}from'../sites/contracts';
const channels=ref<any[]>([]),activity=ref<any>(),sites=ref<Site[]>([]),error=ref(''),notice=ref(''),busy=ref(false),code=ref(''),secret=ref(''),id=ref(''),revision=ref(0),kind=ref('telegram'),system=ref(true),selected=ref<string[]>([]),recipient=ref(''),host=ref(''),port=ref(587),username=ref(''),sender=ref(''),tls=ref('starttls'),enabled=ref(true);const auth=useAuth();
function clear(){secret.value='';code.value=''}
async function load(){channels.value=[];activity.value=undefined;const [a,b]=await Promise.all([request<any[]>('/alert-channels'),request<any>('/alerts')]);channels.value=a||[];activity.value=b}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){channels.value=[];activity.value=undefined;error.value=message(e)}finally{clear();busy.value=false}}
function select(c:any){clear();id.value=c.id;revision.value=c.revision;kind.value=c.kind;system.value=c.system;selected.value=c.site_ids||[];recipient.value=c.recipient;host.value=c.host||'';port.value=c.port||587;username.value=c.username||'';sender.value=c.from||'';tls.value=c.tls_mode||'starttls';enabled.value=c.enabled}
async function save(){await run(async()=>{await request('/alert-channels',{channel:{id:id.value,kind:kind.value,enabled:enabled.value,system:system.value,site_ids:system.value?[]:selected.value,recipient:recipient.value,host:host.value,port:Number(port.value),username:username.value,from:sender.value,tls_mode:tls.value},expected_revision:revision.value,secret:secret.value,totp:code.value},'PUT');await load();notice.value='渠道已保存；送达状态以真实回执为准'})}
async function test(id:string){await run(async()=>{await request('/alert-channels/'+id+'/test',{totp:code.value});await load();notice.value='测试已排队，尚未确认外部送达'})}
onMounted(()=>{window.addEventListener('pagehide',clear);void run(async()=>{await load();sites.value=await all<Site>('/sites')})});onUnmounted(()=>{clear();window.removeEventListener('pagehide',clear)});
</script><template><section><h1>告警与通知渠道</h1><p class="muted">每渠道独立送达回执；测试排队不等于外部已送达。站点范围显式指定，系统告警范围不代表所有站点。</p><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><button @click="run(load)" :disabled="busy">刷新通知状态</button><section v-if="activity" class="panel" data-testid="notification-activity"><h2>事件与送达</h2><p v-for="(i,n) in activity.incidents" :key="n">{{i.kind}} {{i.state}} · 采集延迟 {{i.lag_seconds}} 秒</p><p v-for="d in activity.deliveries" :key="d.id">{{d.channel_id}} {{d.status}} · 第 {{d.attempt}} 次 · {{d.reason}}</p></section><section class="panel"><h2>渠道管理</h2><p v-for="c in channels" :key="c.id"><button @click="select(c)">{{c.kind}} {{c.recipient}}</button> {{c.enabled?'启用':'停用'}} · {{c.system?'SystemOnly':c.site_ids.join(',')}} <button :disabled="busy||!code||auth.actor?.role!=='admin'" @click="test(c.id)">测试此渠道</button></p><fieldset :disabled="busy||auth.actor?.role!=='admin'"><button @click="id='';revision=0;clear()">新建渠道</button><label>渠道类型<select v-model="kind"><option value="telegram">Telegram</option><option value="smtp">SMTP</option></select></label><label>接收地址 / Chat ID<input v-model="recipient"></label><label class="check"><input type="checkbox" v-model="enabled">启用渠道</label><label class="check"><input type="checkbox" v-model="system">仅系统告警（SystemOnly）</label><div v-if="!system"><label class="check" v-for="s in sites" :key="s.id"><input type="checkbox" v-model="selected" :value="s.id">{{s.name}}</label></div><template v-if="kind==='smtp'"><label>SMTP 主机<input v-model="host"></label><label>SMTP 端口<input type="number" v-model="port"></label><label>TLS 模式<select v-model="tls"><option>starttls</option><option>implicit</option></select></label><label>SMTP 用户名<input v-model="username"></label><label>发件地址<input v-model="sender"></label></template><label>新渠道秘密（仅提交）<input type="password" autocomplete="off" v-model="secret"></label><label>渠道操作动态验证码<input inputmode="numeric" autocomplete="off" v-model="code"></label><button @click="save" :disabled="!code">保存渠道并清除秘密</button></fieldset></section></section></template>
